  ('dc000000-0000-4000-8000-000000000001', 'f0000000-0000-4000-8000-000000000001', '제108회 전국체육대회 종합 준비계획', '70000000-0000-4000-8000-000000000001', '2026-03-02T09:31:00+09:00'::timestamptz, '2026-08-05T17:41:00+09:00'::timestamptz),
