-- -----------------------------------------------------------------------------
  id, title, description, status, visibility, department_id, owner_id,
  due_date, fiscal_year, archived_at, created_by, created_at, updated_at
) values
  ('f0000000-0000-4000-8000-000000000001', '제108회 전국체육대회 종합 준비', '2027년 화성시 개최 전국체전의 부서 간 준비 상황을 한곳에서 관리한다. 경기장·수송·안전·홍보·예산 소관 부서가 각자 진행하던 계획을 하나의 업무로 묶어 일정과 결정 사항을 공유한다.', 'doing', 'city', 'd0000000-0000-4000-8000-000000000078', '70000000-0000-4000-8000-000000000001', '2026-10-30'::date, 2026, NULL, '70000000-0000-4000-8000-000000000001', '2026-03-02T09:14:00+09:00'::timestamptz, '2026-08-05T17:41:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000002', '전국체전 경기장 시설 개보수', '종합경기타운·실내체육관 등 8개 시설의 개보수 범위와 공정을 관리한다. 대회 규격 충족 여부는 대한체육회 시설 실사에서 확인한다.', 'doing', 'city', 'd0000000-0000-4000-8000-000000000077', '70000000-0000-4000-8000-000000000005', '2026-09-25'::date, 2026, NULL, '70000000-0000-4000-8000-000000000005', '2026-03-11T10:02:00+09:00'::timestamptz, '2026-08-04T11:20:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000003', '전국체전 수송·교통대책 수립', '선수단·임원·관람객 수송 계획과 대회 기간 교통 통제 방안. 트램 개통 일정과 맞물려 있어 대중교통과·트램건설추진단과 함께 본다.', 'todo', 'city', 'd0000000-0000-4000-8000-000000000049', '70000000-0000-4000-8000-000000000006', '2026-07-28'::date, 2026, NULL, '70000000-0000-4000-8000-000000000006', '2026-05-20T14:30:00+09:00'::timestamptz, '2026-08-03T09:05:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000004', '전국체전 안전관리계획 수립', '다중운집 안전관리계획과 대회 기간 재난 대응 체계. 「공연법」·「재난 및 안전관리 기본법」 검토 결과를 포함한다.', 'review', 'city', 'd0000000-0000-4000-8000-000000000013', '70000000-0000-4000-8000-000000000007', '2026-08-24'::date, 2026, NULL, '70000000-0000-4000-8000-000000000007', '2026-04-08T13:11:00+09:00'::timestamptz, '2026-08-05T15:52:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000005', '2026년 음식물류폐기물 수집·운반 대행 원가산정 용역', '「폐기물관리법」 제14조에 따른 대행 원가 산정. 매년 하반기에 다음 연도 대행료 결정을 위해 반복 시행하며, 산정 결과는 대행업체 계약 협상의 기준이 된다.', 'review', 'department', 'd0000000-0000-4000-8000-000000000088', '70000000-0000-4000-8000-000000000002', '2026-08-14'::date, 2026, NULL, '70000000-0000-4000-8000-000000000002', '2026-06-15T09:40:00+09:00'::timestamptz, '2026-08-05T18:10:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000006', '2025년 음식물류폐기물 수집·운반 대행 원가산정 용역', '작년 시행분. 용역 결과 대행료 단가가 전년 대비 4.1% 인상되었고, 인상률 근거 자료가 시의회 행정사무감사에서 다시 요구되었다.', 'done', 'department', 'd0000000-0000-4000-8000-000000000088', '70000000-0000-4000-8000-000000000002', '2025-09-30'::date, 2025, '2025-12-31T23:59:00+09:00'::timestamptz, '70000000-0000-4000-8000-000000000002', '2025-06-10T10:00:00+09:00'::timestamptz, '2025-10-14T16:30:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000007', '동탄 트램 1호선 개통 대비 시내버스 노선 개편', '트램 개통에 따라 중복 노선을 조정하고 환승 연계를 설계한다. 노선 조정은 주민 민원이 크게 발생하는 사안이라 설명회 이력을 함께 남긴다.', 'doing', 'department', 'd0000000-0000-4000-8000-000000000051', '70000000-0000-4000-8000-000000000004', '2026-11-30'::date, 2026, NULL, '70000000-0000-4000-8000-000000000004', '2026-02-17T11:25:00+09:00'::timestamptz, '2026-08-01T14:03:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000008', '재활용 선별시설 반입수수료 조정', '선별시설 운영원가 상승분을 반영한 반입수수료 조례 개정 검토. 조례 개정이 필요해 의회법무과 협의가 선행되어야 한다.', 'todo', 'department', 'd0000000-0000-4000-8000-000000000088', '70000000-0000-4000-8000-000000000002', '2026-09-04'::date, 2026, NULL, '70000000-0000-4000-8000-000000000002', '2026-07-02T09:12:00+09:00'::timestamptz, '2026-07-29T10:44:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000009', '청소차량 운행기록 전산화', '종량제 수거차량 운행기록을 수기 대장에서 차량 단말 기반으로 전환한다. 민원 발생 시 수거 시각을 확인하는 데 쓰인다.', 'doing', 'department', 'd0000000-0000-4000-8000-000000000088', '70000000-0000-4000-8000-000000000002', '2026-08-28'::date, 2026, NULL, '70000000-0000-4000-8000-000000000002', '2026-04-21T15:33:00+09:00'::timestamptz, '2026-08-02T09:58:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000010', 'AI 행정업무 시범과제 2차 확산', '1차 시범 부서의 활용 결과를 정리하고 확산 대상 부서를 선정한다. 부서별 담당자 교육 일정과 활용 사례를 함께 관리한다.', 'doing', 'city', 'd0000000-0000-4000-8000-000000000054', '70000000-0000-4000-8000-000000000010', '2026-09-11'::date, 2026, NULL, '70000000-0000-4000-8000-000000000010', '2026-05-06T10:15:00+09:00'::timestamptz, '2026-08-05T13:22:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000011', '2027년도 본예산 편성지침 시달', '각 부서 예산 요구서 작성 기준과 제출 일정을 정리해 시달한다. 전국체전 관련 사업은 별도 검토 대상으로 분류한다.', 'todo', 'city', 'd0000000-0000-4000-8000-000000000025', '70000000-0000-4000-8000-000000000009', '2026-09-30'::date, 2026, NULL, '70000000-0000-4000-8000-000000000009', '2026-07-14T09:00:00+09:00'::timestamptz, '2026-07-31T17:12:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000012', '반도체 특화단지 기반시설 인허가 사전협의', '용수·전력 공급 계획에 대한 관계기관 사전협의. 협의 지연이 입주기업 일정에 직접 영향을 주는 사안이다.', 'doing', 'department', 'd0000000-0000-4000-8000-000000000063', '70000000-0000-4000-8000-000000000011', '2026-07-31'::date, 2026, NULL, '70000000-0000-4000-8000-000000000011', '2026-03-30T09:47:00+09:00'::timestamptz, '2026-07-28T16:05:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000013', '국공립어린이집 3개소 신규 설치', '동탄권 2개소·향남권 1개소 설치를 위한 부지 선정과 리모델링 설계. 공동주택 관리동 활용 방안을 병행 검토한다.', 'doing', 'department', 'd0000000-0000-4000-8000-000000000038', '70000000-0000-4000-8000-000000000012', '2026-09-18'::date, 2026, NULL, '70000000-0000-4000-8000-000000000012', '2026-04-02T11:08:00+09:00'::timestamptz, '2026-08-04T14:47:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000014', '화성 뱃놀이 축제 운영계획 수립', '축제 프로그램 구성과 안전관리 계획. 전곡항 일대 교통 통제 범위는 교통정책과와 협의한다.', 'review', 'department', 'd0000000-0000-4000-8000-000000000069', '70000000-0000-4000-8000-000000000008', '2026-08-18'::date, 2026, NULL, '70000000-0000-4000-8000-000000000008', '2026-05-13T10:30:00+09:00'::timestamptz, '2026-08-05T11:19:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000015', '노후 상수관로 정비 3차', '1990년대 매설 구간의 누수 저감을 위한 관로 교체. 굴착 구간이 통학로와 겹쳐 학교 방학 기간에 시행해야 한다.', 'todo', 'department', 'd0000000-0000-4000-8000-000000000087', '70000000-0000-4000-8000-000000000015', '2026-07-24'::date, 2026, NULL, '70000000-0000-4000-8000-000000000015', '2026-06-01T09:20:00+09:00'::timestamptz, '2026-07-20T15:00:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000016', '시민 안전보험 갱신 계약', '전 시민 대상 안전보험 보장 항목 조정 및 갱신 계약 체결. 보장 범위 변경 사항은 시 누리집에 공고했다.', 'done', 'department', 'd0000000-0000-4000-8000-000000000013', '70000000-0000-4000-8000-000000000007', '2026-06-30'::date, 2026, NULL, '70000000-0000-4000-8000-000000000007', '2026-03-05T13:40:00+09:00'::timestamptz, '2026-06-27T16:22:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000017', '전국체전 홍보·미디어 운영계획', '대회 D-500 기점 홍보 로드맵과 미디어센터 운영 방안. 계획 확정 후 추진단 종합계획에 반영했다.', 'done', 'city', 'd0000000-0000-4000-8000-000000000001', '70000000-0000-4000-8000-000000000014', '2026-07-15'::date, 2026, NULL, '70000000-0000-4000-8000-000000000014', '2026-04-17T09:55:00+09:00'::timestamptz, '2026-07-14T18:02:00+09:00'::timestamptz),
  ('f0000000-0000-4000-8000-000000000018', '동탄 트램 시운전 구간 주민설명회', '시운전 구간 인접 주민 대상 설명회 3회 개최 및 제기된 의견 정리. 소음 관련 의견이 다수였다.', 'done', 'city', 'd0000000-0000-4000-8000-000000000005', '70000000-0000-4000-8000-000000000013', '2026-06-20'::date, 2026, NULL, '70000000-0000-4000-8000-000000000013', '2026-04-28T10:10:00+09:00'::timestamptz, '2026-06-23T11:35:00+09:00'::timestamptz)
on conflict (id) do nothing;

